package com.manishrawat.realestate.service; import com.manishrawat.realestate.dao.PropertyDAO; import com.manishrawat.realestate.model.Property; import java.util.*; public class PropertyService {private final PropertyDAO dao=new PropertyDAO(); public int create(Property p)throws Exception{return dao.save(p);} public List<Property> search(String c,String t)throws Exception{return dao.approved(c,t);} public List<Property> all()throws Exception{return dao.findAll();} public void approve(int id,boolean yes)throws Exception{dao.setStatus(id,yes?"APPROVED":"REJECTED");} public List<Property> manager(int id)throws Exception{return dao.findByManager(id);} }
